sys_script_include.script:
var NetworkRequesterInfo = Class.create();
NetworkRequesterInfo.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    getDetails: function() {

        var userSysId = this.getParameter('sysparm_user');
        var result = {};

        var user = new GlideRecord('sys_user');

        if (user.get(userSysId)) {
            result.email = user.getValue('email');
            result.name = user.getValue('name');
            result.phone = user.getValue('mobile_phone');
        }

        return JSON.stringify(result);
    },

    type: 'NetworkRequesterInfo'
});
